#include <array>
#include <cstdio>
#include <filesystem>
#include <iostream>
#include <memory>
#include <stdexcept>

class File {
 public:
  enum class Mode { read, write };

  // Opens the file or throws, so a File never holds a failed open.
  File(const std::filesystem::path& path, Mode mode)
      : handle_(std::fopen(path.c_str(), mode == Mode::read ? "r" : "w")) {
    if (!handle_) throw std::runtime_error("cannot open " + path.string());
  }

  [[nodiscard]] std::FILE* get() const { return handle_.get(); }

 private:
  struct Closer {
    void operator()(std::FILE* f) const noexcept { std::fclose(f); }
  };
  std::unique_ptr<std::FILE, Closer> handle_;
};

int main() {
  {
    const File out("notes.txt", File::Mode::write);
    std::fputs("dock reached\n", out.get());
  }  // closed here, which hands the buffered line to the operating system
  const File in("notes.txt", File::Mode::read);
  std::array<char, 64> line{};
  if (std::fgets(line.data(), static_cast<int>(line.size()), in.get()) != nullptr) std::cout << line.data();
}

