class Recorder {
 public:
  void record(const Reading& r) {
    mutex_.lock();
    if (!r.valid()) return;   // returns with mutex_ locked: the next call waits forever
    readings_.push_back(r);   // can throw std::bad_alloc, with the same result
    mutex_.unlock();
  }

 private:
  std::mutex mutex_;
  std::vector<Reading> readings_;
};

#include <iostream>
#include <stdexcept>
#include <string_view>

// Stands in for a C API that hands out handles and counts how many are still open.
class HandleTable {
 public:
  [[nodiscard]] int open() {
    ++open_;
    return next_++;
  }
  void close(int /*handle*/) { --open_; }
  [[nodiscard]] int still_open() const { return open_; }

 private:
  int next_ = 1;
  int open_ = 0;
};

void parse_by_hand(HandleTable& table, std::string_view line) {
  const int handle = table.open();
  if (line.empty()) return;                                      // leaks handle
  if (line == "garbage") throw std::runtime_error("bad line");  // leaks handle
  table.close(handle);
}

class Handle {
 public:
  explicit Handle(HandleTable& table) : table_(table), id_(table.open()) {}
  ~Handle() { table_.close(id_); }
  Handle(const Handle&) = delete;
  Handle& operator=(const Handle&) = delete;
  Handle(Handle&&) = delete;
  Handle& operator=(Handle&&) = delete;

 private:
  HandleTable& table_;
  int id_;
};

void parse_raii(HandleTable& table, std::string_view line) {
  const Handle handle(table);
  if (line.empty()) return;
  if (line == "garbage") throw std::runtime_error("bad line");
}

using Parser = void (*)(HandleTable&, std::string_view);

[[nodiscard]] int left_open_after(Parser parse) {
  HandleTable table;
  for (const std::string_view line : {"12.5", "", "garbage"}) {
    try {
      parse(table, line);
    } catch (const std::runtime_error&) {
    }
  }
  return table.still_open();
}

int main() {
  std::cout << "by hand: " << left_open_after(parse_by_hand) << " handles left open\n";
  std::cout << "raii:    " << left_open_after(parse_raii) << " handles left open\n";
}

#include <array>
#include <cstdio>
#include <filesystem>
#include <iostream>
#include <optional>
#include <stdexcept>
#include <string>
#include <utility>

class File {
 public:
  enum class Mode { read, write };

  File(const std::filesystem::path& path, Mode mode)
      : f_(std::fopen(path.c_str(), mode == Mode::read ? "r" : "w")) {
    if (f_ == nullptr) throw std::runtime_error("cannot open " + path.string());
  }
  ~File() { close(); }

  File(const File&) = delete;
  File& operator=(const File&) = delete;
  File(File&& other) noexcept : f_(std::exchange(other.f_, nullptr)) {}
  File& operator=(File&& other) noexcept {
    if (this != &other) {
      close();  // ours first, or it leaks
      f_ = std::exchange(other.f_, nullptr);
    }
    return *this;
  }

  [[nodiscard]] std::FILE* get() const { return f_; }

 private:
  void close() noexcept {
    if (f_ != nullptr) std::fclose(f_);
  }
  std::FILE* f_;
};

[[nodiscard]] File open_log(const std::filesystem::path& path) { return File(path, File::Mode::write); }

[[nodiscard]] std::optional<std::string> first_line(const std::filesystem::path& path) {
  const File in(path, File::Mode::read);
  std::array<char, 64> line{};
  if (std::fgets(line.data(), static_cast<int>(line.size()), in.get()) == nullptr) return std::nullopt;
  return line.data();
}

int main() {
  File log = open_log("run.log");
  File moved = std::move(log);
  std::cout << "after move: source " << (log.get() != nullptr ? "open" : "empty") << ", target "
            << (moved.get() != nullptr ? "open" : "empty") << '\n';

  File other("other.log", File::Mode::write);
  std::fputs("written before the move assignment\n", other.get());
  other = std::move(moved);  // closes other.log, which hands its buffered line to the operating system
  std::cout << "other.log holds: " << first_line("other.log").value_or("nothing\n");
}

#include <array>
#include <cstdio>
#include <filesystem>
#include <iostream>
#include <memory>
#include <stdexcept>

struct FileCloser {
  void operator()(std::FILE* f) const noexcept { std::fclose(f); }
};
using FilePtr = std::unique_ptr<std::FILE, FileCloser>;

enum class Mode { read, write };

// Returns an open file or throws, so no caller ever holds a null handle.
[[nodiscard]] FilePtr open_file(const std::filesystem::path& path, Mode mode) {
  FilePtr file(std::fopen(path.c_str(), mode == Mode::read ? "r" : "w"));
  if (!file) throw std::runtime_error("cannot open " + path.string());
  return file;
}

void save_then_fail(const std::filesystem::path& path) {
  const FilePtr out = open_file(path, Mode::write);
  std::fputs("partial result\n", out.get());
  throw std::runtime_error("sensor timeout");  // out is closed while this propagates
}

int main() {
  try {
    save_then_fail("result.txt");
  } catch (const std::runtime_error& e) {
    std::cout << "caught: " << e.what() << '\n';
  }
  const FilePtr in = open_file("result.txt", Mode::read);
  std::array<char, 64> line{};
  if (std::fgets(line.data(), static_cast<int>(line.size()), in.get()) != nullptr) {
    std::cout << "file holds: " << line.data();
  }
}

#include <algorithm>
#include <concepts>
#include <iostream>
#include <stdexcept>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

template <std::invocable F>
class ScopeGuard {
 public:
  [[nodiscard]] explicit ScopeGuard(F f) : f_(std::move(f)) {}
  ~ScopeGuard() {
    if (active_) f_();
  }
  ScopeGuard(const ScopeGuard&) = delete;
  ScopeGuard& operator=(const ScopeGuard&) = delete;
  ScopeGuard(ScopeGuard&&) = delete;
  ScopeGuard& operator=(ScopeGuard&&) = delete;
  void dismiss() noexcept { active_ = false; }

 private:
  F f_;
  bool active_ = true;
};

class Registry {
 public:
  void add(std::string name) { names_.push_back(std::move(name)); }
  void remove_last() noexcept { names_.pop_back(); }  // undoes the latest add, and only that
  [[nodiscard]] bool contains(std::string_view name) const { return std::ranges::find(names_, name) != names_.end(); }
  [[nodiscard]] const std::vector<std::string>& names() const { return names_; }

 private:
  std::vector<std::string> names_;
};

// Stands in for a hardware bus. It reads the sensor's registration while opening it,
// and throws when the sensor doesn't answer.
class Bus {
 public:
  void open(std::string_view sensor, const Registry& registry) const {
    if (!registry.contains(sensor)) throw std::logic_error("register the sensor first");
    if (sensor == "lidar") throw std::runtime_error("lidar did not answer");
  }
};

// Registers the sensor, then opens it. If opening fails, the registration is undone.
void connect(Registry& registry, const Bus& bus, std::string_view sensor) {
  registry.add(std::string(sensor));
  ScopeGuard undo([&] { registry.remove_last(); });
  bus.open(sensor, registry);
  undo.dismiss();
}

int main() {
  Registry registry;
  const Bus bus;
  for (const std::string_view sensor : {"imu", "lidar", "camera"}) {
    try {
      connect(registry, bus, sensor);
    } catch (const std::runtime_error& e) {
      std::cout << "failed: " << e.what() << '\n';
    }
  }
  std::cout << "registered:";
  for (const std::string& name : registry.names()) std::cout << ' ' << name;
  std::cout << '\n';
}

#include <concepts>
#include <utility>

template <std::invocable F>
class ScopeGuard {
 public:
  [[nodiscard]] explicit ScopeGuard(F f) : f_(std::move(f)) {}
  ~ScopeGuard() { f_(); }
  ScopeGuard(const ScopeGuard&) = delete;
  ScopeGuard& operator=(const ScopeGuard&) = delete;
  ScopeGuard(ScopeGuard&&) = delete;
  ScopeGuard& operator=(ScopeGuard&&) = delete;

 private:
  F f_;
};

int main() {
  int restored = 0;
  ScopeGuard([&] { restored = 1; });  // no name: destroyed at the semicolon
  return restored;
}

#include <stdexcept>

struct Closer {
  ~Closer() { throw std::runtime_error("close failed"); }
};

int main() { const Closer c; }

void close_or_throw() { throw std::runtime_error("close failed"); }

struct Closer {
  ~Closer() { close_or_throw(); }  // no throw written here, so no warning
};

int main() {
  try {
    const Closer c;
  } catch (const std::runtime_error& e) {
    std::cout << "caught: " << e.what() << '\n';  // never reached
  }
}

